INSERT INTO common_products
    (name, brand, barcode, unit, category_name, price, gst_rate, image_url, active)
SELECT
    s.name,
    s.brand,
    s.barcode,
    s.unit,
    s.category_name,
    s.price,
    s.gst_rate,
    s.image_url,
    s.active
FROM seed_products s
WHERE NOT EXISTS (
    SELECT 1
    FROM common_products cp
    WHERE cp.barcode = s.barcode
);
